
-- 制作装备升级功能
-- 装备升级数据表
-- DROP TABLE IF EXISTS `item_up`;
CREATE TABLE `item_up` (
  `guid` int(11) AUTO_INCREMENT,-- 自增id，方便删除和变更时找到位置
  `id` int(11) NOT NULL,-- 原始装备id
  `amount` int(11) NOT NULL DEFAULT '0', -- 原始装备的数量
  `upid` int(11) NOT NULL DEFAULT '0', -- 升级后的装备ID
  `chance` tinyint(3) NOT NULL DEFAULT '0', -- 成功几率
  `crazing` tinyint(3) NOT NULL DEFAULT '0', -- 失败是否碎裂：0不碎，1碎
  `id1` int(11) NOT NULL DEFAULT '0', -- 需要的材料1的ID
  `amount1` int(11) NOT NULL DEFAULT '0',-- 需要的材料1的数量
  `id2` int(11) NOT NULL DEFAULT '0', -- 需要的材料2的ID
  `amount2` int(11) NOT NULL DEFAULT '0',-- 需要的材料2的数量
  `baoshi` int(11) NOT NULL DEFAULT '0', -- 幸运串珠ID （防止失败后碎裂）
  `baoshinum` int(11) NOT NULL DEFAULT '0', -- 需要的幸运串珠数量
  PRIMARY KEY (`id`),
UNIQUE KEY `guid` (`guid`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8;

